operations.aliasTransaction:
-- Owner-authorized single canonical history-only alias, following PR #198.
-- Project: wrygicdfxwjnrugduxnt; canonical 20261123090000 -> hosted 20260916190510.
BEGIN;
LOCK TABLE supabase_migrations.schema_migrations IN SHARE ROW EXCLUSIVE MODE;
DO $alias$
DECLARE inserted integer;
BEGIN
 IF (SELECT count(*) FROM supabase_migrations.schema_migrations) <> 294
 OR (SELECT md5(string_agg(row_to_json(m)::text,E'\n' ORDER BY version)) FROM supabase_migrations.schema_migrations m) <> 'bc86f4921f2c1849e0c2d82dc7a23aec'
 THEN RAISE EXCEPTION 'PR258_LEDGER_CHANGED'; END IF;
 IF EXISTS (SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261123090000')
 THEN RAISE EXCEPTION 'PR258_ALIAS_ALREADY_EXISTS'; END IF;
 IF (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version='20260916190510' AND name='sp_credential_organisation_roles'
 AND encode(sha256(convert_to(array_to_string(statements,E'\n'),'UTF8')),'hex')='c05fdadc1ad96543cbcb979a6c39d7b9866615ae957a8fa7925889723334db62') <> 1
 THEN RAISE EXCEPTION 'PR258_APPLICATION_MISMATCH'; END IF;
 INSERT INTO supabase_migrations.schema_migrations(version,name)
 VALUES ('20261123090000','sp_credential_organisation_roles')
 ON CONFLICT(version) DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted <> 1 OR (SELECT count(*) FROM supabase_migrations.schema_migrations) <> 295
 THEN RAISE EXCEPTION 'PR258_ALIAS_COUNT_MISMATCH'; END IF;
END $alias$;
COMMIT;
